js/app.js:423-433:
  try { recorder = new MediaRecorder(mediaStream, mime ? { mimeType: mime } : undefined); }
  catch { stopTimer(); stopMeter(); teardownRecording(); state='idle'; show('idleCard'); toast(...); return; }
