    // Game tokens carry a random nonce and the deck they were minted for, so a token cannot be
    // replayed for a second submission or moved to another deck. Deliberately separate from
    // mintToken/tokenValid, which analyze.js -> feedback.js clip consent still uses.
    export function mintGameToken(gameType) {
      const secret = tokenSecret();
      if (!secret) return '';
      const payload = `${Date.now()}.${randomUUID()}.${gameType}`;
      return `${payload}.${createHmac('sha256', secret).update(payload).digest('hex').slice(0, 32)}`;
    }

    export function readGameToken(token) {
      const secret = tokenSecret();
      if (!secret || typeof token !== 'string') return null;
      const i = token.lastIndexOf('.');
      if (i < 1) return null;
      const payload = token.slice(0, i);
      const sig = Buffer.from(token.slice(i + 1));
      const expect = Buffer.from(createHmac('sha256', secret).update(payload).digest('hex').slice(0, 32));
      if (sig.length !== expect.length || !timingSafeEqual(sig, expect)) return null;
      const [ts, nonce, gameType] = payload.split('.');
      const age = Date.now() - Number(ts);
      if (!Number.isFinite(age) || age < 0 || !nonce) return null;
      return { age, nonce, gameType };
    }

