STEP 1 — add a shared helper just above stopListening (currently line 457). It returns an empty string when the take is worth a call, or the message to show when it is not:

  // The three reasons a take is not worth a call, in one place. Shared by the deliberate stop
  // and the spontaneous one (phone call, Siri, headset disconnect, mic permission revoked
  // mid-take), because an interrupted four-second take is exactly as unreadable as a
  // four-second one someone chose to end. `interrupted` only changes the wording: the user did
  // not press anything, so "that was 4 seconds" would read as the app blaming them.
  function takeRejection(interrupted) {
    const elapsed = (Date.now() - startedAt) / 1000;
    const voicedS = micFrames ? (micVoiced / micFrames) * elapsed : -1;
    if (elapsed < MIN_RECORD_S) {
      return interrupted
        ? `Something took the mic ${Math.round(elapsed)} seconds in, so that take got cut off. Nothing was read from it — start again when you're ready.`
        : `That was ${Math.round(elapsed)} seconds. Under twenty I would be guessing at country scale, so go again and give it twenty or so.`;
    }
    if (micPeak >= 0 && micPeak < 0.02) {
      return 'Your mic barely picked anything up 🎤, check Chrome\'s mic icon (address bar) is using the right microphone, then try again.';
    }
    if (voicedS >= 0 && voicedS < MIN_VOICED_S) {
      return 'I could hardly hear any talking 🤫 get closer and say a couple of sentences.';
    }
    return '';
  }

