EDIT 3 — js/game.js:473-478. The global shortcut handler currently makes the map unusable for aiming and traps Space on buttons. Replace the whole listener with:

document.addEventListener('keydown', (e) => {
  if ($('#dock').hidden || /^(INPUT|TEXTAREA)$/.test(document.activeElement.tagName)) return;
  // Space is a button's own activation key. Swallowing it here meant a keyboard user sitting
  // on 'lock it in' pressed space and the clip played instead of the round locking.
  if (e.code === 'Space' && document.activeElement.tagName === 'BUTTON') return;
  // While the map has focus the arrows are for aiming. Leaflet's pan handler is registered on
  // document at map-focus time, so it runs alongside this one and preventDefault here does not
  // stop it -- without this guard every aiming keypress also skipped 5s and spent the budget.
  const onMap = map && document.activeElement === map.getContainer();
  if (e.code === 'Space') { e.preventDefault(); if (playing) media.pause(); else playClip(); }
  else if (e.key === 'ArrowLeft' && document.activeElement !== playerBar && !onMap) { e.preventDefault(); seekBy(-5); }
