function dealDeck(pool) {
  const labelOf = (c) => String(c.label);
  // Different labels can carry the identical pin: "Delhi, India" and "Delhi-Meerut Region,
  // India" are both 28.6139/77.209, and "Buenos Aires, Argentina" and "Argentina" are both
  // -34.6037/-58.3816. Deduping on the label alone let both into one game, so the amber pin
  // dropped on the same pixel twice - which reads as a bug and hands over the second answer.
  // Key on the coordinate too. Not a distance threshold: Dubai and Sharjah are 22 km apart
  // and are genuinely different answers.
  const pinOf = (c) => `${Number(c.lat).toFixed(2)},${Number(c.lng).toFixed(2)}`;
  const bag = shuffle(pool);
  const out = [];
  const usedLabels = new Set();
  const usedPins = new Set();
  for (const c of bag) {
    if (out.length >= ROUNDS) break;
    if (usedLabels.has(labelOf(c)) || usedPins.has(pinOf(c))) continue;
    usedLabels.add(labelOf(c));
    usedPins.add(pinOf(c));
    out.push(c);
  }
  // a deck with fewer distinct places than rounds still gets a full game
  for (const c of bag) {
    if (out.length >= ROUNDS) break;
    if (!out.includes(c)) out.push(c);
  }
  return out;
}

