function replacementClip() {
  const usedIds = new Set(deck.map((c) => c.id));
  const pinOf = (c) => `${Number(c.lat).toFixed(2)},${Number(c.lng).toFixed(2)}`;
  // don't reuse a pin the player has already been shown this game
  const usedPins = new Set(deck.filter((c, i) => i !== round).map(pinOf));
  const pool = (window.CLIPS[gameType] || []).filter((c) => !usedIds.has(c.id));
  const fresh = pool.filter((c) => !usedPins.has(pinOf(c)));
  const pick = fresh.length ? fresh : pool;
  return pick.length ? pick[Math.floor(Math.random() * pick.length)] : deck[round];
}

