with:

```js
// Whole-page shortcuts: space toggles play, arrows nudge — as long as you're not typing a
// nickname, and never while a button has focus (space is how you press a focused button).
document.addEventListener('keydown', (e) => {
  if ($('#dock').hidden) return;
  const el = document.activeElement;
  if (!el || /^(INPUT|TEXTAREA|SELECT)$/.test(el.tagName) || el.isContentEditable) return;
  if (e.code === 'Space') {
