    // aged >=75s, so re-minting at submit time is always 'too fast'). Three spaced attempts:
    // a mint that lands even 30s into a game is old enough by the time anyone finishes.
    // The gen check matters as much as the retry: without it, a chain armed by a game the
    // player abandoned lands mid-way through a LATER game and replaces that game's honest
    // token with a fresh one, so a properly played run gets rejected as 'too_fast'.
    const mint = (attempt) => fetch('/api/scores?start=1', { signal: AbortSignal.timeout(8000) })
      .then((r) => r.json())
